<?php
$_SERVER['HTTP_HOST']='localhost';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../models/User.php';require_once __DIR__.'/../services/CredentialService.php';require_once __DIR__.'/../includes/jwt.php';require_once __DIR__.'/../database/SchemaMigrator.php';
function clAssert(bool$ok,string$message):void{if(!$ok)throw new RuntimeException($message);}function clThrows(callable$fn,int$status):void{try{$fn();throw new RuntimeException('Expected credential rejection');}catch(CredentialValidationException$e){clAssert($e->status===$status,'wrong rejection status');}}
$db=(new Database())->getConnection();$users=[];$passed=0;$failed=0;$run=function(string$name,callable$test)use(&$passed,&$failed):void{try{$test();$passed++;echo"PASS: {$name}\n";}catch(Throwable$e){$failed++;fwrite(STDERR,"FAIL: {$name} - {$e->getMessage()}\n");}};
try{$create=function(string$label,string$password='oldPassword123')use($db,&$users):int{$s=$db->prepare("INSERT INTO users(email,password,first_name)VALUES(?,?, 'Credential')");$s->execute(['cl-'.$label.'-'.bin2hex(random_bytes(5)).'@example.invalid',password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$db->lastInsertId();$users[]=$id;return$id;};$owner=$create('owner');$foreign=$create('foreign');$service=new CredentialService($db);
    $run('missing current password and malformed new passwords are rejected',function()use($service,$owner):void{clThrows(fn()=>$service->changePassword($owner,['new_password'=>'newPassword456']),422);clThrows(fn()=>$service->changePassword($owner,['current_password'=>'oldPassword123','new_password'=>'short']),422);clThrows(fn()=>$service->changePassword($owner,['current_password'=>'oldPassword123','new_password'=>str_repeat('x',73)]),422);clThrows(fn()=>$service->changePassword($owner,['current_password'=>'oldPassword123','new_password'=>['not'=>'string']]),422);});
    $run('confirmation mismatch and same-password changes are rejected',function()use($service,$owner):void{clThrows(fn()=>$service->changePassword($owner,['current_password'=>'oldPassword123','new_password'=>'newPassword456','new_password_confirmation'=>'differentPass789']),422);clThrows(fn()=>$service->changePassword($owner,['current_password'=>'oldPassword123','new_password'=>'oldPassword123']),422);});
    $run('wrong current password preserves hash and token version',function()use($db,$service,$owner):void{$before=$db->query("SELECT password,token_version FROM users WHERE id={$owner}")->fetch();clThrows(fn()=>$service->changePassword($owner,['current_password'=>'wrongPassword0','new_password'=>'newPassword456']),401);$after=$db->query("SELECT password,token_version FROM users WHERE id={$owner}")->fetch();clAssert($before===$after,'failed change mutated credentials or sessions');});
    $run('valid change hashes new password, revokes old versions, and ignores foreign identity fields',function()use($db,$service,$owner,$foreign):void{$tokenA=JWT::encode(['user_id'=>$owner]);$tokenB=JWT::encode(['user_id'=>$owner]);$a=JWT::decode($tokenA);$b=JWT::decode($tokenB);clAssert($a['jti']!==$b['jti'],'sessions are not uniquely identified');$result=$service->changePassword($owner,['current_password'=>'oldPassword123','new_password'=>'newPassword456','new_password_confirmation'=>'newPassword456','user_id'=>$foreign,'email'=>'foreign@example.invalid']);$row=$db->query("SELECT password,token_version,password_changed_at FROM users WHERE id={$owner}")->fetch();clAssert(password_verify('newPassword456',$row['password']),'new password hash is invalid');clAssert(!password_verify('oldPassword123',$row['password']),'old password still verifies');clAssert((int)$row['token_version']===(int)$a['token_version']+1,'token version was not advanced');clAssert($row['password_changed_at']!==null,'password change timestamp missing');clAssert(JWT::getUserIdFromToken($tokenA)===false&&JWT::getUserIdFromToken($tokenB)===false,'old session helper still accepts revoked tokens');$rotated=JWT::encode(['user_id'=>$owner,'token_version'=>$result['token_version']]);clAssert(JWT::getUserIdFromToken($rotated)===$owner,'rotated session helper rejected current token');clAssert((int)$db->query("SELECT token_version FROM users WHERE id={$foreign}")->fetchColumn()===1,'foreign credential state changed');clAssert($result['token_version']===(int)$row['token_version'],'returned version is inconsistent');});
    $run('real login model rejects old password and accepts new password',function()use($db,$owner):void{$model=new User();$email=$db->query("SELECT email FROM users WHERE id={$owner}")->fetchColumn();clAssert($model->login($email,'oldPassword123')===false,'old password login succeeded');clAssert((int)$model->login($email,'newPassword456')['id']===$owner,'new password login failed');});
    $run('injected failure rolls back password and session version atomically',function()use($db,$create):void{$id=$create('rollback','rollbackOld123');$before=$db->query("SELECT password,token_version,password_changed_at FROM users WHERE id={$id}")->fetch();$probe=new CredentialService($db,function($point){if($point==='after_credential_update')throw new RuntimeException('Injected');});try{$probe->changePassword($id,['current_password'=>'rollbackOld123','new_password'=>'rollbackNew456']);throw new RuntimeException('failure injection did not throw');}catch(RuntimeException$e){clAssert($e->getMessage()==='Injected','unexpected failure');}$after=$db->query("SELECT password,token_version,password_changed_at FROM users WHERE id={$id}")->fetch();clAssert($before===$after,'rollback left half-changed credential/session state');});
    $run('two concurrent old-password changes allow at most one transition',function()use($db,$create):void{if(!function_exists('proc_open'))throw new RuntimeException('proc_open unavailable');$id=$create('concurrent','concurrentOld123');$barrier=sys_get_temp_dir().DIRECTORY_SEPARATOR.'sanie-credential-'.bin2hex(random_bytes(8)).'.start';$worker=__DIR__.DIRECTORY_SEPARATOR.'CredentialChangeConcurrencyWorker.php';$processes=[];foreach(['concurrentNewA456','concurrentNewB456']as$next){$pipes=[];$process=proc_open([PHP_BINARY,$worker,(string)$id,base64_encode('concurrentOld123'),base64_encode($next),$barrier],[1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('worker start failed');$processes[]=[$process,$pipes];}touch($barrier);$results=[];foreach($processes as[$process,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);$decoded=json_decode($out,true);if($exit!==0||!is_array($decoded))throw new RuntimeException("worker failed {$err} {$out}");$results[]=$decoded;}if(file_exists($barrier))unlink($barrier);clAssert(count(array_filter($results,fn($r)=>!empty($r['ok'])))===1,'concurrent changes did not serialize: '.json_encode($results));$row=$db->query("SELECT password,token_version FROM users WHERE id={$id}")->fetch();clAssert((int)$row['token_version']===2,'concurrent transition advanced version more than once');clAssert(password_verify('concurrentNewA456',$row['password']) xor password_verify('concurrentNewB456',$row['password']),'final concurrent password is inconsistent');});
    $run('Phase 11 migration is current and repeat-safe',function()use($db):void{$a=(new SchemaMigrator($db))->run();$b=(new SchemaMigrator($db))->run();clAssert(!$a['applied']&&!$b['applied'],'migration was not a no-op');clAssert($a['migration_id']===SchemaMigrator::PHASE11_MIGRATION_ID,'wrong migration ID');});
}finally{foreach(array_reverse($users)as$id){try{$db->prepare('DELETE FROM users WHERE id=?')->execute([$id]);}catch(Throwable$ignored){}}}echo"RESULT: {$passed} passed, {$failed} failed, 0 skipped\n";exit($failed?1:0);
